example_conversion.pydantic_model:
from typing import List, Optional from pydantic import BaseModel, Field
class Location(BaseModel): """Location coordinates""" latitude: float = Field(description="Latitude") longitude: float = Field(description="Longitude")
class ToolInput(BaseModel): """Input schema for the tool""" truck_id: str = Field(description="Truck identifier") temperature: float = Field(description="Current temperature") alerts: Optional[List[str]] = Field(None, description="List of alerts") location: Location = Field(description="Current location")
